#include<bits/stdc++.h>
#define int long long
using namespace std;
vector<int>v[111111];
int f[111111],a[111111],d[111111];
int dp[555555][22],vis[111111];
int fff[111111];
int aa[111111],bb[111111];
int ans=0;


void dfs(int p,int g,int fa){
	dp[p][0]=fa;
	d[p]=g;
	for(int i=1;i<=20;i++){
		dp[p][i]=dp[dp[p][i-1]][i-1];
	}
	for(int i=0;i<v[p].size();i++){
		if(v[p][i]!=fa){
			f[v[p][i]]=p;
			dfs(v[p][i],g+1,p);
		}
	}
}
int ff(int p){
	int x=a[p];
	for(int i=0;i<v[p].size();i++){
		if(vis[v[p][i]]==0){
			vis[v[p][i]]=1;
			x+=ff(v[p][i]);
		}
	}
	return fff[p]=x;
}
int lca(int x,int y){
	if(d[x]<d[y]){
		swap(x,y);
	}
	for(int i=20;i>=0;i--){
		if(d[dp[x][i]]>=d[y]){
			x=dp[x][i];
		}
	}
	if(x==y){
		return x;
	}
	for(int i=20;i>=0;i--){
		if(dp[x][i]!=dp[y][i]){
			x=dp[x][i];
			y=dp[y][i];
		}
	}    
	return dp[x][0];
}
void ffff(int p){
	for(int i=0;i<v[p].size();i++){
		if(vis[v[p][i]]==0){
			vis[v[p][i]]=1;
			if(fff[v[p][i]]!=0){
				ans+=min(fff[v[p][i]]*aa[v[p][i]],bb[v[p][i]]);
			}
			ffff(v[p][i]);
		}
	}
}
signed main(){
	ios::sync_with_stdio(0);cin.tie(0);cout.tie(0);
	int n;
	cin>>n;
	for(int i=1;i<n;i++){
		int x,y;
		cin>>x>>y>>aa[i]>>bb[i];
		v[x].push_back(y);
		v[y].push_back(x);
	}
	dfs(1,0,0);
	for(int i=2;i<=n;i++){
		int x=i,y=i-1;
		a[x]+=1;
		a[y]+=1;
		a[f[lca(x,y)]]-=1;
		a[lca(x,y)]-=1;
	}
	ff(1);
	memset(vis,0,sizeof(vis));
	ffff(1);
	cout<<ans;
    return 0;
}
